/// How the client reaches the core: one call at a time, and the event stream.
abstract interface class PostTransport {
  /// Run [method] with [params] (JSON values); its result, a JSON value.
  Future<Object?> call(String method, Map<String, Object?> params);

  /// Live events, each a JSON object.
  Stream<Map<String, Object?>> get events;
}

/// The local API: what the app can ask of the core.
abstract interface class PostApi {
  /// Live events.
  Stream<Event> get events;

  /// This account's devices, oldest first.
  Future<List<Device>> devices();

  /// Name one of this account's devices.
  ///
  /// - [device]: The device's ID.
  /// - [name]: Its new name.
  Future<void> renameDevice({required String device, required String name});

  /// Make a single-use invite code for someone to create an account with
  /// (hosts only), valid for `days`.
  ///
  /// The code is shown once.
  ///
  /// - [bot]: For a bot account.
  /// - [days]: Days until it expires, 1 to 30.
  Future<Invite> createInvite({bool bot = false, int days = 7});

  /// Make someone an admin of a group, or stop them being one.
  ///
  /// - [conversation]: The group.
  /// - [username]: The member's username.
  /// - [admin]: True to make them an admin, false to remove the role.
  Future<void> setAdmin({required String conversation, required String username, required bool admin});

  /// A conversation's messages, newest last.
  ///
  /// - [conversation]: The conversation.
  /// - [before]: Only messages before this one.
  /// - [limit]: At most this many.
  /// - [since]: Only messages sent after this (Unix ms).
  Future<List<Message>> messages({required String conversation, String? before, int limit = 50, DateTime? since});

  /// Messages matching a search.
  ///
  /// - [query]: Words to find, if any.
  /// - [senders]: Only from these people.
  /// - [conversations]: Only in these conversations, if given.
  /// - [tags]: Also with these tags.
  Future<List<Message>> search({String? query, required List<String> senders, List<String>? conversations, List<String> tags = const <String>[]});

  /// Set or clear the banner's fill.
  ///
  /// - [fill]: The fill, or none to clear it.
  Future<void> setBannerFill({Fill? fill});

  /// Set the profile's colours.
  ///
  /// - [theme]: The fill.
  /// - [kind]: What kind of picture it frames.
  /// - [presence]: Its presence for now.
  Future<void> setTheme({required Fill theme, required PictureKind kind, required Presence presence});

  /// Whether the client is connected.
  Future<bool> isConnected();

  /// Forget what is cached.
  Future<void> clearCache();

  /// This account's username, if it has one yet.
  Future<String?> identity();

  /// How many messages are stored.
  Future<int> messageCount();

  /// A greeting.
  ///
  /// - [name]: Who to greet.
  /// - [times]: How often.
  /// - [loud]: Shout it.
  Future<String> greet({String name = 'you', int times = 1, bool loud = false});

  /// The time on the server's clock for one on this device's (Unix ms).
  ///
  /// - [at]: This device's time (Unix ms).
  Future<int> serverTime({required DateTime at});

  /// Start a direct conversation.
  ///
  /// - [username]: Who with.
  Future<String> startDm({required String username});

  /// Create the account.
  ///
  /// - [server]: The server's address.
  /// - [invite]: The invite code.
  Future<void> register({required String server, required String invite});
}

